SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) OR variant_id=ANY(ARRAY['2f074dd6-a27f-4dfd-9ccb-5d741daa5dd4','a61ef170-e692-4768-a4ec-4276dd681ee5','cc9f78f5-8239-49a5-af99-fb39b3f9fdba']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) OR variant_id=ANY(ARRAY['2f074dd6-a27f-4dfd-9ccb-5d741daa5dd4','a61ef170-e692-4768-a4ec-4276dd681ee5','cc9f78f5-8239-49a5-af99-fb39b3f9fdba']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) OR variant_id=ANY(ARRAY['2f074dd6-a27f-4dfd-9ccb-5d741daa5dd4','a61ef170-e692-4768-a4ec-4276dd681ee5','cc9f78f5-8239-49a5-af99-fb39b3f9fdba']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['44c0fd56-5d24-4545-9a11-313bf3252953','e1d523e5-69ea-4e97-858d-1e65d4a07cd5','2af65062-f444-40b2-810a-233ee09da5b3']::uuid[]) OR variant_id=ANY(ARRAY['2f074dd6-a27f-4dfd-9ccb-5d741daa5dd4','a61ef170-e692-4768-a4ec-4276dd681ee5','cc9f78f5-8239-49a5-af99-fb39b3f9fdba']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[])) ORDER BY scope,identity;